/* Terminal model registry defaults and placeholder artwork.
   The live registry is the "models" collection (Admin › Terminal Models); these defaults fill gaps
   so the landing page works before the data loads. SIMULATORS lists the simulators that exist in
   code - a model can only be Available when its simulator is listed here. */
(function () {
  const SIMULATORS = { move3500: 'Move/3500 (VIKING)', lane3600: 'Lane/3600 (VIKING, shares the Move/3500 menu)' };
  /* Hardware profiles. VIKING (menu, flows, translations, knowledge) is shared: "data" names the model whose menu and
     knowledge a simulator uses. Everything that differs on the physical terminal is listed here, not copied.
     Lane/3600 (Martin, 9 Nov 2026): works like the Move/3500 with its own layout; ECR-integrated (no Wi-Fi or SIM/mobile network). */
  const HW = {
    move3500: { id: 'move3500', data: 'move3500' },
    lane3600: {
      id: 'lane3600', data: 'move3500', lane: true,
      // Same VIKING menus and screens as the Move/3500. From Martin's video of a Lane/3600 (9 Nov 2026):
      // no keys under the screen; F opens the main menu after the merchant card (or code); menus scroll by swiping
      // on the touchscreen; settings change with the arrows on the screen; red at the merchant code shows
      // "Cancelled by operator"; Copy menu has 3 items and says "No reconciliation to copy" when there is none.
      laneIdle: true,          // "Waiting for Amount" over the logo, alternating with the logo alone
      menuAuth: true,          // F asks for the merchant card first
      opCancel: true,          // red at the merchant code: "Cancelled by operator", then the start screen
      noReconCopy: true,       // Copy menu › Last reconciliation without one: "No reconciliation to copy"
      swipeScroll: true,       // menus scroll by swiping on the screen
      touchArrows: true,       // < > on the settings screens (photos)
      rowTap: false,           // not confirmed that tapping a row opens it
      noShortcut: true,        // no ▼ key - the ShortCut menu can't be opened
      noControlPanel: true,    // no F1 key - how the Control panel opens isn't known yet
      noPowerKeys: true,       // mains powered: no ". + yellow" switch-off (not confirmed)
      ecr: true,               // amounts can also come from the cash register
      hideFields: ['apn', 'gsmPin'],
      dropValues: { commType: ['GPRS', 'Wifi'], ecrComm: ['IP Wifi'] },
      hideNodes: ['m35-copy-defauth'],
      defaults: { ecr: 'Yes' },
      // Texts that differ on the Lane/3600 screen (video 9 Nov 2026)
      tr: { da: { 'n:m35-003': 'Sidste afstemn.', 'n:m35-004': 'Sidste Z-Total' } },
      // Troubleshooting written for a battery terminal with base, SIM or Wi-Fi doesn't apply to a Lane/3600
      hideTrouble: '\\b(mobile|SIM|Wi-?Fi|Bluetooth|base|modem|battery|GPRS|APN)\\b'
    }
  };
  const DEFAULT_MODELS = {
    move3500: { name: 'Ingenico Move/3500', shortName: 'Move/3500', slug: 'move3500', simulator: 'move3500', status: 'available', order: 1, description: 'Portable terminal with built-in printer. Connection options vary by version.' },
    desk3500: { name: 'Ingenico Desk/3500', shortName: 'Desk/3500', slug: 'desk3500', simulator: null, status: 'soon', order: 2, description: 'Countertop terminal with printer.' },
    lane3000: { name: 'Ingenico Lane/3000', shortName: 'Lane/3000', slug: 'lane3000', simulator: null, status: 'soon', order: 3, description: 'Compact PIN pad connected to a cash register.' },
    lane3600: { name: 'Ingenico Lane/3600', shortName: 'Lane/3600', slug: 'lane3600', simulator: 'lane3600', status: 'soon', order: 4, description: 'ECR-integrated payment terminal with touchscreen, connected to a cash register.' },
    n950: { name: 'SmartPOS N950', shortName: 'SmartPOS N950', slug: 'n950', simulator: null, status: 'soon', order: 5, description: 'Android terminal with touchscreen and printer.' },
    p300: { name: 'SmartPOS P300', shortName: 'SmartPOS P300', slug: 'p300', simulator: null, status: 'soon', order: 6, description: 'Android PIN pad with keypad and wide screen for cash registers.' }
  };
  const key = (x, y, w, h, fill, txt, tc) => '<rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" rx="5" fill="' + fill + '" stroke="#c9ced8" stroke-width="1.2"/>' + (txt ? '<text x="' + (x + w / 2) + '" y="' + (y + h / 2 + 5) + '" text-anchor="middle" font-family="Arial" font-size="14" font-weight="700" fill="' + (tc || '#fff') + '">' + txt + '</text>' : '');
  const keypad = (x0, y0, kw, kh, gx, gy, side) => {
    let s = ''; const L = ['1', '2', '3', '4', '5', '6', '7', '8', '9', '', '0', ''];
    L.forEach((t, i) => { const c = i % 3, r = Math.floor(i / 3); s += key(x0 + c * (kw + gx), y0 + r * (kh + gy), kw, kh, '#16181d', t); });
    if (side) ['#d8282f', '#f2c618', '#21b04b'].forEach((col, i) => { s += key(x0 + 3 * (kw + gx) + 4, y0 + (i + 1) * (kh + gy), kw + 6, kh, col, ''); });
    return s;
  };
  const cl = (cx, cy, c) => '<g fill="none" stroke="' + (c || '#8a93a3') + '" stroke-width="2" stroke-linecap="round"><path d="M' + cx + ' ' + (cy - 6) + 'a8 8 0 0 1 0 12"/><path d="M' + (cx + 5) + ' ' + (cy - 10) + 'a13 13 0 0 1 0 20"/><path d="M' + (cx + 10) + ' ' + (cy - 14) + 'a18 18 0 0 1 0 28"/></g>';
  const svg = b => '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 220 400" role="img">' + b + '</svg>';
  const ART = {
    // Lane/3000: compact black PIN pad, small colour screen, keypad with red/yellow/green keys on the right, no printer.
    lane3000: svg('<defs><linearGradient id="l3b" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#3a3f48"/><stop offset="1" stop-color="#1b1e24"/></linearGradient></defs>' +
      '<rect x="30" y="60" width="160" height="300" rx="26" fill="url(#l3b)"/>' + cl(104, 82) +
      '<rect x="46" y="100" width="128" height="96" rx="6" fill="#0e1116"/><rect x="51" y="105" width="118" height="86" rx="2" fill="#2f63c9"/><rect x="51" y="105" width="118" height="18" fill="#1f4aa3"/>' +
      '<text x="110" y="161" text-anchor="middle" font-family="Arial" font-size="12" fill="#dfe9fb">Lane/3000</text>' + keypad(48, 212, 28, 24, 5, 8, true)),
    // SmartPOS N950: Android terminal - large touchscreen, built-in printer at the top, no physical keypad.
    n950: svg('<defs><linearGradient id="n9b" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#40454f"/><stop offset="1" stop-color="#202329"/></linearGradient></defs>' +
      '<rect x="36" y="14" width="148" height="372" rx="22" fill="url(#n9b)"/><rect x="48" y="22" width="124" height="44" rx="12" fill="#2b2f36"/><rect x="62" y="40" width="96" height="5" rx="2.5" fill="#0d0f12"/><path d="M70 42 L70 12 L150 12 L150 42" fill="#f6f6f2" stroke="#d6d4cc"/>' +
      '<rect x="46" y="78" width="128" height="250" rx="10" fill="#0d0f12"/><rect x="51" y="83" width="118" height="240" rx="6" fill="#eef2f8"/><rect x="51" y="83" width="118" height="16" rx="6" fill="#d9e1ee"/>' +
      [0, 1, 2].map(r => [0, 1, 2].map(c => '<rect x="' + (62 + c * 34) + '" y="' + (120 + r * 46) + '" width="26" height="26" rx="7" fill="' + ['#2f7bf5', '#f2a33a', '#21b04b', '#8a63d2', '#e6604f', '#19a1b7', '#0e2a5c', '#9aa3b1', '#5b8def'][r * 3 + c] + '"/>').join('')).join('') +
      '<text x="110" y="295" text-anchor="middle" font-family="Arial" font-size="12" fill="#3b475c">SmartPOS</text><rect x="94" y="340" width="32" height="5" rx="2.5" fill="#5a606b"/><rect x="70" y="372" width="80" height="6" rx="3" fill="#121418"/>'),
    // SmartPOS P300: compact Android PIN pad - touchscreen, no printer.
    p300: svg('<defs><linearGradient id="p3b" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#3d424b"/><stop offset="1" stop-color="#1e2127"/></linearGradient></defs>' +
      '<rect x="44" y="50" width="132" height="300" rx="24" fill="url(#p3b)"/>' + cl(104, 70) +
      '<rect x="54" y="88" width="112" height="216" rx="9" fill="#0d0f12"/><rect x="59" y="93" width="102" height="206" rx="5" fill="#eef2f8"/>' +
      [0, 1, 2, 3].map(r => [0, 1, 2].map(c => '<rect x="' + (66 + c * 30) + '" y="' + (150 + r * 34) + '" width="26" height="28" rx="5" fill="#ffffff" stroke="#c9d1de"/>').join('')).join('') +
      '<text x="110" y="128" text-anchor="middle" font-family="Arial" font-size="15" font-weight="700" fill="#0e2a5c">0,00</text><rect x="94" y="318" width="32" height="5" rx="2.5" fill="#5a606b"/><rect x="74" y="338" width="72" height="5" rx="2.5" fill="#121418"/>')
  };
  // Photos of the terminals on their start screen (Move/3500: the simulator's own photo).
  const PHOTO = { lane3600: 'data:image/webp;base64,', p300: 'data:image/webp;base64,', n950: 'data:image/webp;base64,', desk3500: 'data:image/webp;base64,', lane3000: 'data:image/webp;base64,', move3500: 'data:image/webp;base64,' };
  window.FC_MODELS = { SIMULATORS, HW, DEFAULT_MODELS, PHOTO, ART: Object.fromEntries(Object.entries(ART).map(([k, v]) => [k, 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(v)])) };
})();
